const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const volcano = ee.Geometry.Point(-19.62, 63.63); // Eyjafjallajökull
  const roi = volcano.buffer(50000); // 50km buffer around volcano

  // Specific date: May 10, 2010
  const startDate = '2010-05-10';
  const endDate = '2010-05-11';

  // 2. Data Acquisition - Try MODIS Terra first
  let modisTerra = ee.ImageCollection('MODIS/006/MOD09GA')
    .filterDate(startDate, endDate)
    .filterBounds(roi);

  let modisCount = modisTerra.size().getInfo();
  console.log(`MODIS Terra images: ${modisCount}`);

  let collection = modisTerra;

  // Fallback to MODIS Aqua if Terra has no data
  if (modisCount === 0) {
    console.log('Trying MODIS Aqua...');
    let modisAqua = ee.ImageCollection('MODIS/006/MYD09GA')
      .filterDate(startDate, endDate)
      .filterBounds(roi);

    let aquaCount = modisAqua.size().getInfo();
    console.log(`MODIS Aqua images: ${aquaCount}`);

    if (aquaCount === 0) {
      // Try Landsat 7 as last resort (SLC-on in 2010)
      console.log('Trying Landsat 7...');
      let landsat = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterDate(startDate, endDate)
        .filterBounds(roi);

      let landsatCount = landsat.size().getInfo();
      console.log(`Landsat 7 images: ${landsatCount}`);

      if (landsatCount === 0) {
        console.log('<answer>C1</answer>');
        return;
      }
      collection = landsat;
    } else {
      collection = modisAqua;
    }
  }

  // Get the first image
  let image = ee.Image(collection.first());

  // 3. Processing - Create true color and mask clouds

  // For MODIS
  if (collection.getInfo().id.includes('MODIS')) {
    // MODIS true color: bands 1, 4, 3 (R,G,B)
    image = image.select(['sur_refl_b01', 'sur_refl_b04', 'sur_refl_b03']);

    // Simple cloud mask using MODIS quality band
    let qa = image.select('sur_refl_b01').gt(0); // Valid reflectance > 0
    image = image.updateMask(qa);
  } 
  // For Landsat
  else if (collection.getInfo().id.includes('LANDSAT')) {
    // Landsat true color: bands 3,2,1
    image = image.select(['SR_B3', 'SR_B2', 'SR_B1']);

    // Apply scale factors
    image = image.multiply(0.0000275).add(-0.2);

    // Simple cloud mask using QA band
    let qa = image.select('SR_B1').gt(0);
    image = image.updateMask(qa);
  }

  // 4. Identify plume pixels (high reflectance in red band)
  let redBand = image.select(0); // First band is red
  let plumeMask = redBand.gt(0.3); // Threshold for bright plume

  // Create latitude image
  let latImage = ee.Image.pixelLonLat().select('latitude');

  // Get mean latitude of plume pixels
  let stats = plumeMask.addBands(latImage).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  let meanLat = stats.get('latitude_mean').getInfo();
  let pixelCount = stats.get('latitude_count').getInfo();

  console.log(`Plume pixel count: ${pixelCount}`);
  console.log(`Mean plume latitude: ${meanLat}`);
  console.log(`Volcano latitude: 63.63`);

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (meanLat === null || meanLat === undefined || 
      isNaN(meanLat) || meanLat < 50 || meanLat > 70) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Determine if plume is primarily northward
  // If mean plume latitude > volcano latitude + 0.1 degrees (~11 km north)
  if (meanLat > 63.73) {
    console.log('<answer>A</answer>');
  } else if (meanLat < 63.53) {
    console.log('<answer>B</answer>');
  } else {
    // Plume centered around volcano, ambiguous direction
    console.log('<answer>C3</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
